create or replace function gov_repo.ai_system_evidence_report(p_system_id uuid)
returns table(evidence_category text,evidence_id uuid,evidence_code varchar,title varchar,evidence_type gov_repo.evidence_type,status gov_repo.evidence_status,verified_at timestamptz,retention_until date,classification gov_repo.classification_level,collected_at timestamptz,eu_ai_act_article text,is_mandatory boolean)
language sql security definer as $$
select 'Technical Documentation (Art. 11 + Annex IV)'::text,e.evidence_id,e.evidence_code,e.title,e.evidence_type,e.status,e.verified_at,e.retention_until,e.classification,e.collected_at,'Art. 11 + Annex IV'::text,true from gov_repo.ai_systems s join gov_repo.evidence e on e.evidence_id=s.technical_doc_evidence_id where s.system_id=p_system_id and s.technical_doc_evidence_id is not null
union all select 'Declaration of Conformity (Art. 47)'::text,e.evidence_id,e.evidence_code,e.title,e.evidence_type,e.status,e.verified_at,e.retention_until,e.classification,e.collected_at,'Art. 47(2)'::text,(s.risk_class='high') from gov_repo.ai_systems s join gov_repo.evidence e on e.evidence_id=s.declaration_of_conformity_id where s.system_id=p_system_id and s.declaration_of_conformity_id is not null
union all select 'Risk Management System (Art. 9)'::text,e.evidence_id,e.evidence_code,e.title,e.evidence_type,e.status,e.verified_at,e.retention_until,e.classification,e.collected_at,'Art. 9'::text,(s.risk_class='high') from gov_repo.ai_systems s join gov_repo.evidence e on e.evidence_id=s.risk_mgmt_evidence_id where s.system_id=p_system_id and s.risk_mgmt_evidence_id is not null
union all select 'Post-Market Surveillance Plan (Art. 72)'::text,e.evidence_id,e.evidence_code,e.title,e.evidence_type,e.status,e.verified_at,e.retention_until,e.classification,e.collected_at,'Art. 72'::text,(s.risk_class='high') from gov_repo.ai_systems s join gov_repo.evidence e on e.evidence_id=s.pms_plan_evidence_id where s.system_id=p_system_id and s.pms_plan_evidence_id is not null
union all select 'Fundamental Rights Impact Assessment (Art. 9(9))'::text,e.evidence_id,e.evidence_code,e.title,e.evidence_type,e.status,e.verified_at,e.retention_until,e.classification,e.collected_at,'Art. 9(9)'::text,(s.risk_class='high') from gov_repo.ai_systems s join gov_repo.evidence e on e.evidence_id=s.fria_evidence_id where s.system_id=p_system_id and s.fria_evidence_id is not null
union all select 'Bias & Fairness Assessment (Art. 9(7))'::text,e.evidence_id,e.evidence_code,e.title,e.evidence_type,e.status,e.verified_at,e.retention_until,e.classification,e.collected_at,'Art. 9(7)'::text,false from gov_repo.ai_systems s join gov_repo.evidence e on e.evidence_id=s.bias_assessment_evidence_id where s.system_id=p_system_id and s.bias_assessment_evidence_id is not null
union all select 'Adversarial Testing — GPAI Systemic Risk (Art. 55)'::text,e.evidence_id,e.evidence_code,e.title,e.evidence_type,e.status,e.verified_at,e.retention_until,e.classification,e.collected_at,'Art. 55(1)(a)'::text,(s.gpai_tier='gpai_systemic_risk') from gov_repo.ai_systems s join gov_repo.evidence e on e.evidence_id=s.adversarial_testing_evidence_id where s.system_id=p_system_id and s.adversarial_testing_evidence_id is not null
union all select 'Annex III Exception Justification (Art. 6(3))'::text,e.evidence_id,e.evidence_code,e.title,e.evidence_type,e.status,e.verified_at,e.retention_until,e.classification,e.collected_at,'Art. 6(3)'::text,s.annex_iii_exception_claimed from gov_repo.ai_systems s join gov_repo.evidence e on e.evidence_id=s.annex_iii_exception_evidence_id where s.system_id=p_system_id and s.annex_iii_exception_evidence_id is not null
order by 12 desc,1; $$;
